pub use error::LexError;
pub use escape::unescape;
pub use stats::Stats;
pub use token::{tokenize, Token, Tokens};
use std::io::{self, BufRead};
use std::process::ExitCode;

use logscan::Stats;

fn main() -> ExitCode {
    let mut stats = Stats::default();
    let mut stdin = io::stdin().lock();
    let mut line = String::new();
    loop {
        line.clear();
        match stdin.read_line(&mut line) {
            Ok(0) => break,
            Ok(_) => stats.add_line(line.trim_end_matches(['\r', '\n'])),
            Err(error) => {
                eprintln!("logscan: cannot read stdin: {error}");
                return ExitCode::from(1);
            }
        }
    }
    println!("lines: {}", stats.lines);
    println!("rejected lines: {}", stats.rejected_lines);
    println!("timestamps: {}", stats.timestamps);
    println!("pairs: {}", stats.pairs);
    println!("words: {}", stats.words);
    ExitCode::SUCCESS
}
use std::borrow::Cow;

/// Resolves the escapes of a quoted value as the tokenizer hands it out. Borrows when there is nothing to resolve.
pub fn unescape(raw: &str) -> Cow<'_, str> {
    if !raw.contains('\\') {
        return Cow::Borrowed(raw);
    }
    let mut text = String::with_capacity(raw.len());
    let mut chars = raw.chars();
    while let Some(c) = chars.next() {
        if c != '\\' {
            text.push(c);
            continue;
        }
        match chars.next() {
            Some('n') => text.push('\n'),
            Some('t') => text.push('\t'),
            Some(other) => text.push(other),
            None => text.push('\\'),
        }
    }
    Cow::Owned(text)
}
# logscan

Reads structured log lines from stdin and prints how many lines, timestamps, `key=value` pairs and bare words it
saw. The nightly import runs it over log dumps of several gigabytes, so the tokenizer is on the hot path: it
borrows every token from the input line and does not allocate.

```console
$ printf '[2024-05-01T12:00:00Z] level=info msg="started \\"worker\\"" user=ann\n' | logscan
lines: 1
rejected lines: 0
timestamps: 1
pairs: 3
words: 0
```

## Line format

```text
[2024-05-01T12:00:00Z] level=info msg="disk 91% full" retries= done
```

- `[...]` is a timestamp. It is kept as written, without the brackets.
- `key=value` is a pair. The value is bare (up to the next space or tab, may be empty) or double-quoted. A quoted
  value may contain spaces and the escapes `\"`, `\\`, `\n` and `\t`; it is handed out as written, escapes
  included. `logscan::unescape` resolves them for callers that need the text.
- Anything else up to the next space or tab is a word.
- Tokens are separated by spaces or tabs. The first malformed token ends the line's token stream with an error.

## Development

```console
cargo test
```
---TESTS---
use logscan::{tokenize, LexError, Token};

fn tokens(line: &str) -> Result<Vec<Token<'_>>, LexError> {
    tokenize(line).collect()
}

#[test]
fn reads_a_typical_line() {
    assert_eq!(
        tokens("[2024-05-01T12:00:00Z] level=info msg=\"disk 91% full\" user=ann").unwrap(),
        vec![
            Token::Timestamp("2024-05-01T12:00:00Z"),
            Token::Key("level"),
            Token::Bare("info"),
            Token::Key("msg"),
            Token::Quoted("disk 91% full"),
            Token::Key("user"),
            Token::Bare("ann"),
        ]
    );
}

#[test]
fn quoted_values_keep_their_escapes() {
    assert_eq!(
        tokens(r#"msg="say \"hi\"\n""#).unwrap(),
        vec![Token::Key("msg"), Token::Quoted(r#"say \"hi\"\n"#)]
    );
}

#[test]
fn words_stand_alone() {
    assert_eq!(
        tokens("started worker-3 ok").unwrap(),
        vec![Token::Word("started"), Token::Word("worker-3"), Token::Word("ok")]
    );
}

#[test]
fn tabs_separate_tokens_like_spaces() {
    assert_eq!(
        tokens("a=1\tb=2").unwrap(),
        vec![Token::Key("a"), Token::Bare("1"), Token::Key("b"), Token::Bare("2")]
    );
}

#[test]
fn empty_line_has_no_tokens() {
    assert_eq!(tokens("").unwrap(), vec![]);
    assert_eq!(tokens("   \t ").unwrap(), vec![]);
}

#[test]
fn unterminated_quote_is_an_error() {
    assert_eq!(
        tokens("msg=\"never closed"),
        Err(LexError::UnterminatedQuote { pos: 4 })
    );
}

#[test]
fn unterminated_timestamp_is_an_error() {
    assert_eq!(
        tokens("[2024-05-01 level=info"),
        Err(LexError::UnterminatedTimestamp { pos: 0 })
    );
}

#[test]
fn iteration_stops_after_an_error() {
    let mut stream = tokenize("ok =bad later=1");
    assert_eq!(stream.next(), Some(Ok(Token::Word("ok"))));
    assert_eq!(stream.next(), Some(Err(LexError::EmptyKey { pos: 3 })));
    assert_eq!(stream.next(), None);
}
