        let n = b.len();
        let mut p = self.pos;
        match self.st {
            0 => {
                while p < n && (b[p] == b' ' || b[p] == b'\t') {
                    p += 1;
                }
                if p >= n {
                    self.pos = p;
                    return None;
                }
