use crate::error::LexError;

/// One piece of a log line, borrowed from the line itself.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Token<'a> {
    /// The text between `[` and `]`.
    Timestamp(&'a str),
    /// The name in front of `=`.
    Key(&'a str),
    /// A double-quoted value without its quotes, escapes left as written.
    Quoted(&'a str),
    /// An unquoted value; empty for `key=` followed by a space or the end of the line.
    Bare(&'a str),
    /// A run of characters that is neither a timestamp nor part of a pair.
    Word(&'a str),
}

/// Where the scanner is in the line.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum State {
    /// At the start of a token, possibly after separating blanks.
    Token,
    /// Just past the `=` of a key; the value comes next.
    Value,
    /// The end of the line was reached or an error was reported.
    Done,
}

/// Streams the tokens of one line. After the first error it yields nothing more.
#[derive(Debug, Clone)]
pub struct Tokens<'a> {
    src: &'a str,
    pos: usize,
    state: State,
}

/// Tokenizes one log line without copying any of it.
pub fn tokenize(line: &str) -> Tokens<'_> {
    Tokens {
        src: line,
        pos: 0,
        state: State::Token,
    }
}

/// Space and tab are the only separators between tokens.
#[inline]
fn is_blank(byte: u8) -> bool {
    byte == b' ' || byte == b'\t'
}

impl<'a> Iterator for Tokens<'a> {
    type Item = Result<Token<'a>, LexError>;

    fn next(&mut self) -> Option<Self::Item> {
        let item = match self.state {
            State::Done => return None,
            State::Token => self.next_token().transpose(),
            State::Value => {
                self.state = State::Token;
                Some(self.next_value())
            }
        };
        if !matches!(item, Some(Ok(_))) {
            self.state = State::Done;
        }
        item
    }
}

impl<'a> Tokens<'a> {
    /// Reads the token that starts at the next non-blank byte. `Ok(None)` means the line is used up.
    fn next_token(&mut self) -> Result<Option<Token<'a>>, LexError> {
        let bytes = self.src.as_bytes();
        let start = skip_blanks(bytes, self.pos);
        self.pos = start;
        let Some(&first) = bytes.get(start) else {
            return Ok(None);
        };
        match first {
            b'[' => self.timestamp(start).map(Some),
            b'"' => Err(LexError::UnexpectedQuote { pos: start }),
            b'=' => Err(LexError::EmptyKey { pos: start }),
            _ => self.key_or_word(start).map(Some),
        }
    }

    /// Reads the value after `key=`, which is empty when a blank or the end of the line comes first.
    fn next_value(&mut self) -> Result<Token<'a>, LexError> {
        let bytes = self.src.as_bytes();
        let start = self.pos;
        match bytes.get(start) {
            None => {
                self.pos = start;
                Ok(Token::Bare(self.slice(start, start)))
            }
            Some(&byte) if is_blank(byte) => {
                self.pos = start;
                Ok(Token::Bare(self.slice(start, start)))
            }
            Some(b'"') => self.quoted(start),
            Some(_) => self.bare(start),
        }
    }

    /// `[...]`; the text between the brackets is the timestamp.
    fn timestamp(&mut self, open: usize) -> Result<Token<'a>, LexError> {
        let bytes = self.src.as_bytes();
        let text_start = open + 1;
        let mut i = text_start;
        loop {
            match bytes.get(i).copied() {
                None => return Err(LexError::UnterminatedTimestamp { pos: open }),
                Some(b']') => break,
                Some(b'[') => return Err(LexError::NestedBracket { pos: i }),
                Some(_) => i += 1,
            }
        }
        self.expect_separator(i + 1)?;
        self.pos = i + 1;
        Ok(Token::Timestamp(self.slice(text_start, i)))
    }

    /// A run of non-blank bytes up to an `=` (a key) or the next blank (a word).
    fn key_or_word(&mut self, start: usize) -> Result<Token<'a>, LexError> {
        let bytes = self.src.as_bytes();
        let mut i = start;
        while let Some(&byte) = bytes.get(i) {
            if is_blank(byte) || byte == b'=' {
                break;
            }
            if byte == b'"' {
                return Err(LexError::UnexpectedQuote { pos: i });
            }
            i += 1;
        }
        if bytes.get(i) == Some(&b'=') {
            self.state = State::Value;
            self.pos = i + 1;
            Ok(Token::Key(self.slice(start, i)))
        } else {
            self.pos = i;
            Ok(Token::Word(self.slice(start, i)))
        }
    }

    /// `"..."` with `\"`, `\\`, `\n` and `\t` as the only escapes.
    fn quoted(&mut self, open: usize) -> Result<Token<'a>, LexError> {
        let bytes = self.src.as_bytes();
        let text_start = open + 1;
        let mut i = text_start;
        loop {
            match bytes.get(i).copied() {
                None => return Err(LexError::UnterminatedQuote { pos: open }),
                Some(b'"') => break,
                Some(b'\\') => match bytes.get(i + 1).copied() {
                    None => return Err(LexError::UnterminatedQuote { pos: open }),
                    Some(b'"' | b'\\' | b'n' | b't') => i += 2,
                    Some(_) => return Err(LexError::InvalidEscape { pos: i }),
                },
                Some(_) => i += 1,
            }
        }
        self.expect_separator(i + 1)?;
        self.pos = i + 1;
        Ok(Token::Quoted(self.slice(text_start, i)))
    }

    /// An unquoted value: a run of non-blank bytes. A quote anywhere in it is an error.
    fn bare(&mut self, start: usize) -> Result<Token<'a>, LexError> {
        let bytes = self.src.as_bytes();
        let mut i = start;
        while let Some(&byte) = bytes.get(i) {
            if is_blank(byte) {
                break;
            }
            if byte == b'"' {
                return Err(LexError::UnexpectedQuote { pos: i });
            }
            i += 1;
        }
        self.pos = i;
        Ok(Token::Bare(self.slice(start, i)))
    }

    /// A token must be followed by a blank or the end of the line.
    fn expect_separator(&self, at: usize) -> Result<(), LexError> {
        match self.src.as_bytes().get(at) {
            Some(&byte) if !is_blank(byte) => Err(LexError::ExpectedSeparator { pos: at }),
            _ => Ok(()),
        }
    }

    fn slice(&self, from: usize, to: usize) -> &'a str {
        &self.src[from..to]
    }
}

/// The index of the first byte at or after `from` that is not a blank.
fn skip_blanks(bytes: &[u8], mut from: usize) -> usize {
    while bytes.get(from).is_some_and(|&byte| is_blank(byte)) {
        from += 1;
    }
    from
}

