mod error;
mod old_token;

use std::hint::black_box;
use std::time::Instant;

fn old_all(line: &str) -> Vec<String> {
    let mut out: Vec<String> = old_token::tokenize(line).map(|t| format!("{t:?}")).collect();
    out.push("END".into());
    out
}

fn new_all(line: &str) -> Vec<String> {
    let mut stream = logscan::tokenize(line);
    let mut out: Vec<String> = Vec::new();
    for t in stream.by_ref() {
        out.push(format!("{t:?}"));
    }
    // After the stream ends it must keep yielding nothing.
    assert!(stream.next().is_none());
    out.push("END".into());
    out
}

fn check(line: &str, failures: &mut u64, checked: &mut u64) {
    *checked += 1;
    let a = old_all(line);
    let b = new_all(line);
    if a != b {
        *failures += 1;
        if *failures <= 10 {
            eprintln!("MISMATCH on {line:?}\n  old: {a:?}\n  new: {b:?}");
        }
    }
}

fn exhaustive(alphabet: &[char], max_len: usize, failures: &mut u64, checked: &mut u64) {
    // Odometer over all strings of length 0..=max_len.
    for len in 0..=max_len {
        let mut idx = vec![0usize; len];
        loop {
            let s: String = idx.iter().map(|&i| alphabet[i]).collect();
            check(&s, failures, checked);
            // advance
            let mut k = 0;
            loop {
                if k == len {
                    break;
                }
                idx[k] += 1;
                if idx[k] < alphabet.len() {
                    break;
                }
                idx[k] = 0;
                k += 1;
            }
            if k == len {
                break;
            }
        }
    }
}

struct Lcg(u64);
impl Lcg {
    fn next(&mut self) -> u64 {
        self.0 = self.0.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407);
        self.0 >> 33
    }
}

fn random_lines(alphabet: &[char], count: usize, max_len: usize, failures: &mut u64, checked: &mut u64) {
    let mut rng = Lcg(0x9E3779B97F4A7C15);
    for _ in 0..count {
        let len = (rng.next() as usize) % (max_len + 1);
        let s: String = (0..len)
            .map(|_| alphabet[(rng.next() as usize) % alphabet.len()])
            .collect();
        check(&s, failures, checked);
    }
}

fn corpus(lines: usize) -> Vec<String> {
    let mut rng = Lcg(42);
    let users = ["ann", "bob", "carol", "dave"];
    let levels = ["info", "warn", "error", "debug"];
    (0..lines)
        .map(|i| {
            let r = rng.next();
            match r % 20 {
                0 => format!("[2024-05-01T12:00:{:02}Z] level=info msg=\"unterminated {i}", i % 60),
                1 => format!("[2024-05-01T12:00:00Z] msg=\"bad \\x escape\" user={}", users[i % 4]),
                2 => format!("started worker-{} ok =oops", i % 9),
                _ => format!(
                    "[2024-05-01T12:{:02}:{:02}Z] level={} msg=\"disk {}% full\\n retry\" user={} retries= job-{} done",
                    i % 60,
                    (i / 60) % 60,
                    levels[(r as usize) % 4],
                    (r % 100),
                    users[(r as usize / 7) % 4],
                    i
                ),
            }
        })
        .collect()
}

fn consume_old(lines: &[String]) -> usize {
    let mut acc = 0usize;
    for line in lines {
        for t in old_token::tokenize(line) {
            acc += match t {
                Ok(_) => 1,
                Err(_) => 2,
            };
        }
    }
    acc
}

fn consume_new(lines: &[String]) -> usize {
    let mut acc = 0usize;
    for line in lines {
        for t in logscan::tokenize(line) {
            acc += match t {
                Ok(_) => 1,
                Err(_) => 2,
            };
        }
    }
    acc
}

fn bench(label: &str, mut f: impl FnMut() -> usize) -> f64 {
    let mut best = f64::MAX;
    let mut sink = 0;
    for _ in 0..7 {
        let start = Instant::now();
        sink ^= black_box(f());
        best = best.min(start.elapsed().as_secs_f64());
    }
    println!("{label:>4}: best of 7 = {:.1} ms (checksum {sink})", best * 1e3);
    best
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    if args.get(1).map(String::as_str) == Some("bench") {
        let lines = corpus(3_000_000);
        let bytes: usize = lines.iter().map(|l| l.len()).sum();
        println!("corpus: {} lines, {:.1} MB", lines.len(), bytes as f64 / 1e6);
        // Alternate to reduce the chance that one ordering benefits from warm caches.
        let o1 = bench("old", || consume_old(&lines));
        let n1 = bench("new", || consume_new(&lines));
        let n2 = bench("new", || consume_new(&lines));
        let o2 = bench("old", || consume_old(&lines));
        println!("new/old ratio: {:.3} (first pair), {:.3} (second pair)", n1 / o1, n2 / o2);
        return;
    }

    let alphabet = ['a', '=', '"', '\\', 'n', '[', ']', ' ', '\t', 'é'];
    let mut failures = 0u64;
    let mut checked = 0u64;
    exhaustive(&alphabet, 6, &mut failures, &mut checked);
    println!("exhaustive: checked {checked}, mismatches {failures}");
    let before = checked;
    random_lines(&alphabet, 2_000_000, 60, &mut failures, &mut checked);
    println!("random: checked {}, total mismatches {failures}", checked - before);
    let fixed: Vec<String> = corpus(200_000);
    for line in &fixed {
        check(line, &mut failures, &mut checked);
    }
    println!("corpus lines: total checked {checked}, total mismatches {failures}");
    if failures > 0 {
        std::process::exit(1);
    }
}

