use std::hint::black_box;
use std::time::Instant;

fn old_all(line: &str) -> Vec<String> {
    let mut out: Vec<String> = old_token::tokenize(line).map(|t| format!("{t:?}")).collect();
    out.push("END".into());
    out
}

fn new_all(line: &str) -> Vec<String> {
    let mut stream = logscan::tokenize(line);
    let mut out: Vec<String> = Vec::new();
    for t in stream.by_ref() {
        out.push(format!("{t:?}"));
    }
    // After the stream ends it must keep yielding nothing.
    assert!(stream.next().is_none());
    out.push("END".into());
    out
}

fn check(line: &str, failures: &mut u64, checked: &mut u64) {
    *checked += 1;
    let a = old_all(line);
    let b = new_all(line);
    if a != b {
        *failures += 1;
        if *failures <= 10 {
            eprintln!("MISMATCH on {line:?}\n  old: {a:?}\n  new: {b:?}");
        }
    }
}

fn exhaustive(alphabet: &[char], max_len: usize, failures: &mut u64, checked: &mut u64) {
    // Odometer over all strings of length 0..=max_len.
    for len in 0..=max_len {
        let mut idx = vec![0usize; len];
        loop {
            let s: String = idx.iter().map(|&i| alphabet[i]).collect();
            check(&s, failures, checked);
            // advance
            let mut k = 0;
            loop {
                if k == len {
                    break;
                }
                idx[k] += 1;
                if idx[k] < alphabet.len() {
                    break;
                }
                idx[k] = 0;
                k += 1;
            }
            if k == len {
                break;
            }
        }
    }
}

